}

.experiments-loading,
.experiments-error,
.experiments-empty {
    color: rgba(180, 180, 180, 0.95);
    margin-top: 18px;
    font-size: 0.9375rem;
}

.experiments-empty {
    margin-top: 24px;
    text-align: center;
    font-weight: 500;
    line-height: 1.55;
    padding: 28px 20px;
    border: 1px solid rgba(255, 255, 255, 0.09);
    border-radius: 14px;
    background: rgba(0, 0, 0, 0.2);
    max-width: 520px;
    margin-left: auto;
    margin-right: auto;
}

.experiments-error {
    color: #e8a0a0;
}

.experiments-list {
    margin-top: 20px;
}

.experiments-list-intro {
    color: rgba(165, 165, 165, 0.95);
    margin-bottom: 16px;
    font-size: 0.9375rem;
    line-height: 1.5;
    max-width: 42em;
}

.experiments-id-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 10px;
    max-width: 480px;
}

.experiments-id-link {
    display: block;
    padding: 14px 18px;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    background: linear-gradient(165deg, rgba(52, 52, 56, 0.45) 0%, rgba(24, 24, 28, 0.65) 100%);
    color: #e8dcc8;
    text-decoration: none;
    font-weight: 600;
    font-size: 0.9rem;
    font-family: ui-monospace, "SF Mono", Menlo, monospace;
    transition:
        border-color 0.2s ease,
        background 0.2s ease,
        transform 0.15s ease;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.experiments-id-link:hover {
    border-color: rgba(192, 159, 83, 0.45);
    background: linear-gradient(165deg, rgba(72, 68, 58, 0.55) 0%, rgba(32, 30, 26, 0.75) 100%);
    color: #faf6ee;
}

.experiments-id-link:active {
    transform: translateY(1px);
}

.experiments-back {
    margin-left: 10px;
    padding: 8px 14px;
    font-size: 0.8125rem;
    font-weight: 600;
    font-family: inherit;
    color: #c8c8c8;
    background: rgba(0, 0, 0, 0.2);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 10px;
    cursor: pointer;
    transition:
        color 0.2s ease,
        border-color 0.2s ease,
        background 0.2s ease;
}

.experiments-back:hover {
    color: #f0f0f0;
    border-color: rgba(192, 159, 83, 0.4);
    background: rgba(192, 159, 83, 0.08);
}

.experiments-back:focus-visible {
    outline: 2px solid rgba(192, 159, 83, 0.55);
    outline-offset: 2px;
}

/* ——— Variant grid ——— */
.experiments-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(min(100%, 380px), 1fr));
    gap: clamp(18px, 3vw, 26px);
    margin-top: 8px;
}

/* ——— Single variant card ——— */
.experiment-card {
    position: relative;
    border-radius: 16px;
    padding: clamp(18px, 3vw, 24px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    background: linear-gradient(168deg, rgba(52, 52, 56, 0.55) 0%, rgba(22, 22, 26, 0.92) 100%);
    box-shadow:
        0 20px 48px rgba(0, 0, 0, 0.35),
        inset 0 1px 0 rgba(255, 255, 255, 0.05);
    color: rgba(200, 200, 200, 0.98);
    display: flex;
    flex-direction: column;
    gap: 20px;
    overflow: hidden;
}

.experiment-card::before {
    content: "";
    position: absolute;
    top: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 38%;
    max-width: 160px;
    height: 3px;
    border-radius: 0 0 10px 10px;
    background: linear-gradient(90deg, transparent, rgba(192, 159, 83, 0.75), transparent);
    pointer-events: none;
    opacity: 0.85;
}

.experiment-card--winning {
    border-color: rgba(192, 159, 83, 0.42);
    box-shadow:
        0 0 0 1px rgba(192, 159, 83, 0.12),
        0 22px 56px rgba(0, 0, 0, 0.42),
        inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.experiment-card--winning::before {
    opacity: 1;
    width: 48%;
    max-width: 200px;
    background: linear-gradient(90deg, transparent, rgba(192, 159, 83, 0.95), transparent);
}

.experiment-card__header {
    display: flex;
    flex-direction: column;
    gap: 14px;
    padding-bottom: 4px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.07);
}

.experiment-card__title-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 10px 14px;
}

.experiment-card__variant {
    margin: 0;
    font-size: clamp(1.05rem, 2.4vw, 1.35rem);
    font-weight: 650;
    letter-spacing: -0.02em;
    color: #f4f4f4;
    line-height: 1.25;
    word-break: break-word;
}

.experiment-card__winning-badge {
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: #faf6ee;
    padding: 6px 12px;
    border-radius: 999px;
    border: 1px solid rgba(192, 159, 83, 0.5);
    background: linear-gradient(180deg, rgba(192, 159, 83, 0.32) 0%, rgba(140, 115, 60, 0.22) 100%);
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
}

.experiment-card__meta {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
}

.experiment-card__chip {
    display: inline-flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 4px;
    padding: 10px 14px;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.09);
    background: rgba(0, 0, 0, 0.28);
    font-size: 0.8125rem;
    line-height: 1.35;
    color: #dcdcdc;
    max-width: 100%;
    word-break: break-word;
}

.experiment-card__chip-key {
    font-size: 0.625rem;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: rgba(192, 159, 83, 0.92);
}

/* ——— Chart row ——— */
.experiment-card__charts {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
}

.experiment-card__chart-panel {
    padding: 14px 12px 16px;
    border-radius: 14px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(0, 0, 0, 0.22);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    min-width: 0;
}

.experiment-card__chart-inner {
    width: 124px;
    height: 124px;
    position: relative;
    margin: 0 auto 4px;
}

.experiment-card__chart-inner canvas {
    max-width: 100% !important;
    max-height: 100% !important;
}

.experiment-card__chart-caption {
    font-size: 0.6875rem;
    font-weight: 700;
    letter-spacing: 0.11em;
    text-transform: uppercase;
    color: rgba(192, 159, 83, 0.95);
    margin-top: 4px;
}

.experiment-card__chart-hint {
    font-size: 0.6875rem;
    color: rgba(150, 150, 150, 0.9);
    margin-top: 4px;
    line-height: 1.35;
    max-width: 11rem;
}

/* ——— Metrics ——— */
.experiment-card__metrics-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 16px 20px;
}

.experiment-card__section {
    min-width: 0;
    padding: 14px 14px 12px;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.06);
    background: rgba(0, 0, 0, 0.15);
}

.experiment-card__section-title {
    margin: 0 0 12px;
    font-size: 0.625rem;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: rgba(192, 159, 83, 0.92);
}

.experiment-card__metrics {
    list-style: none;
    margin: 0;
    padding: 0;
}

.experiment-card__metrics li {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 12px;
    padding: 8px 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
    font-size: 0.8125rem;
}

.experiment-card__metrics li:last-child {
    border-bottom: none;
    padding-bottom: 0;
}

.experiment-card__metrics .metric-label {
    color: rgba(165, 165, 165, 0.98);
    flex: 1;
    min-width: 0;
}

.experiment-card__metrics .metric-value {
    font-weight: 650;
    font-variant-numeric: tabular-nums;
    color: #ececec;
    text-align: right;
    flex-shrink: 0;
}

.experiments-filters {
    display: flex;
    gap: 10px;
    align-items: center;
    justify-content: flex-end;
}

@media screen and (max-width: 640px) {
    .experiment-card__charts {
        grid-template-columns: 1fr;
    }

    .experiment-card__metrics-grid {
        grid-template-columns: 1fr;
    }
}

@media screen and (max-width: 900px) {
    .experiments-grid {
        grid-template-columns: 1fr;
    }
}
